package com.corp.member.model.dto;

import com.corp.member.model.entity.Member;

public record MemberResponse(
    Long id,
    String email,
    String displayName,
    Integer age,
    String membershipCode
) {
    public static MemberResponse fromEntity(Member entity) {
        if (entity == null) return null;
        return new MemberResponse(
            entity.getId(),
            entity.getEmail(),
            entity.getDisplayName(),
            entity.getAge(),
            entity.getMembershipCode()
        );
    }
}

