package com.corp.member.repository;

import com.corp.member.model.entity.Member;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.persistence.EntityManager;
import jakarta.transaction.Transactional;

import java.util.List;
import java.util.Optional;

@ApplicationScoped
public class MemberRepository {

    @Inject
    EntityManager em;

    @Transactional
    public Member save(Member entity) {
        if (entity.getId() == null) {
            em.persist(entity);
            return entity;
        }
        return em.merge(entity);
    }

    public Optional<Member> findById(Long id) {
        return Optional.ofNullable(em.find(Member.class, id));
    }

    public List<Member> findAll() {
        return em.createQuery("FROM Member", Member.class).getResultList();
    }

    public boolean existsById(Long id) {
        return em.find(Member.class, id) != null;
    }

    @Transactional
    public void deleteById(Long id) {
        Member entity = em.find(Member.class, id);
        if (entity != null) {
            em.remove(entity);
        }
    }
}

