package com.corp.member.service.impl;

import com.corp.member.model.dto.CreateMemberRequest;
import com.corp.member.model.dto.MemberResponse;
import com.corp.member.model.entity.Member;
import com.corp.member.repository.MemberRepository;
import com.corp.member.service.MemberService;
import com.corp.member.exception.ResourceNotFoundException;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@ApplicationScoped
public class MemberServiceImpl implements MemberService {

    private final MemberRepository repository;

    @Inject
    public MemberServiceImpl(MemberRepository repository) {
        this.repository = repository;
    }

    @Override
    @Transactional
    public MemberResponse create(CreateMemberRequest request) {
        Member entity = new Member();
        entity.setEmail(request.email());
        entity.setDisplayName(request.displayName());
        entity.setAge(request.age());
        entity.setMembershipCode(request.membershipCode());
        Member saved = repository.save(entity);
        return MemberResponse.fromEntity(saved);
    }

    @Override
    public MemberResponse findById(Long id) {
        Member entity = repository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Member not found with id: " + id));
        return MemberResponse.fromEntity(entity);
    }

    @Override
    public List<MemberResponse> findAll() {
        return repository.findAll().stream()
                .map(MemberResponse::fromEntity)
                .collect(Collectors.toList());
    }

    @Override
    public void delete(Long id) {
        if (!repository.existsById(id)) {
            throw new ResourceNotFoundException("Member not found with id: " + id);
        }
        repository.deleteById(id);
    }
}

