package com.corp.notes.service.impl;

import com.corp.notes.model.dto.CreateNoteRequest;
import com.corp.notes.model.dto.NoteResponse;
import com.corp.notes.model.entity.Note;
import com.corp.notes.repository.NoteRepository;
import com.corp.notes.service.NoteService;
import com.corp.notes.exception.ResourceNotFoundException;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@ApplicationScoped
public class NoteServiceImpl implements NoteService {

    private final NoteRepository repository;

    @Inject
    public NoteServiceImpl(NoteRepository repository) {
        this.repository = repository;
    }

    @Override
    @Transactional
    public NoteResponse create(CreateNoteRequest request) {
        Note entity = new Note();
        entity.setBody(request.body());
        Note saved = repository.save(entity);
        return NoteResponse.fromEntity(saved);
    }

    @Override
    public NoteResponse findById(Long id) {
        Note entity = repository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Note not found with id: " + id));
        return NoteResponse.fromEntity(entity);
    }

    @Override
    public List<NoteResponse> findAll() {
        return repository.findAll().stream()
                .map(NoteResponse::fromEntity)
                .collect(Collectors.toList());
    }

    @Override
    public void delete(Long id) {
        if (!repository.existsById(id)) {
            throw new ResourceNotFoundException("Note not found with id: " + id);
        }
        repository.deleteById(id);
    }
}

