    public boolean existsById(Long id) {
        return em.find(Product.class, id) != null;
    }

    @Transactional
    public void deleteById(Long id) {
        Product entity = em.find(Product.class, id);
        if (entity != null) {
            em.remove(entity);
        }
    }
}

