package com.corp.invoice.repository;

import com.corp.invoice.model.entity.Invoice;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.persistence.EntityManager;
import jakarta.transaction.Transactional;

import java.util.List;
import java.util.Optional;

@ApplicationScoped
public class InvoiceRepository {

    @Inject
    EntityManager em;

    @Transactional
    public Invoice save(Invoice entity) {
        if (entity.getId() == null) {
            em.persist(entity);
            return entity;
        }
        return em.merge(entity);
    }

    public Optional<Invoice> findById(Long id) {
        return Optional.ofNullable(em.find(Invoice.class, id));
    }

    public List<Invoice> findAll() {
        return em.createQuery("FROM Invoice", Invoice.class).getResultList();
    }

    public boolean existsById(Long id) {
        return em.find(Invoice.class, id) != null;
    }

    @Transactional
    public void deleteById(Long id) {
        Invoice entity = em.find(Invoice.class, id);
        if (entity != null) {
            em.remove(entity);
        }
    }
}

